<script>
const TASK_MODES = [
  { value: 'chat',    label: 'Chat',       icon: 'fa-solid fa-message' },
  { value: 'task',    label: 'Document',   icon: 'fa-solid fa-file-lines' },
  { value: 'topic',   label: 'Discussion', icon: 'fa-solid fa-comments' },
]

const DEFAULT_NEW_TASK = () => ({
  name: '',
  mode: 'chat',
  status: 'todo',
  parentId: null,
  selectedProfiles: [],
  llm_model: null
})

const DEFAULT_COLUMN_EDITOR = () => ({
  open: false,
  isNew: true,
  id: null,
  title: '',
  status: 'todo'
})

export default {
  name: 'SprintBoardModals',
  props: {
    sprintId: { type: String, default: null },
    sprintTitle: { type: String, default: 'Sprint' }
  },
  emits: ['task-created', 'tasks-added', 'save-column', 'delete-column'],
  data() {
    return {
      showNewTask: false,
      showAddExisting: false,
      newTask: DEFAULT_NEW_TASK(),
      candidateSearch: '',
      selected: [],
      taskModes: TASK_MODES,
      columnEditor: DEFAULT_COLUMN_EDITOR(),
      columnToRemove: null
    }
  },
  computed: {
    allChats() {
      return Object.values(this.$storex.chats.chats || {})
    },
    // Chats not already in this sprint (and not templates / channels)
    candidateTasks() {
      const q = this.candidateSearch?.trim().toLowerCase()
      return this.allChats
        .filter(c => c?.id && !c.is_template && c.mode !== 'channel')
        .filter(c => !(c.sprints || []).includes(this.sprintId))
        .filter(c => !q || (c.name || '').toLowerCase().includes(q))
        .sort((a, b) => (a.name || '').localeCompare(b.name || ''))
    },
    parentName() {
      if (!this.newTask.parentId) return null
      return this.$storex.chats.chats?.[this.newTask.parentId]?.name || null
    },
    // Friendly label for the column the new task will land in
    targetStatusLabel() {
      return this.$storex.chats.statusLabel(this.newTask.status)
    },
    // Statuses selectable for a column, disabling the ones already in use
    columnStatusOptions() {
      const currentId = this.columnEditor.id
      const usedByOthers = this.$storex.kanban.sprintColumns
        .filter(c => c.id !== currentId)
        .map(c => c.status)
      return this.$storex.chats.statusList.map(s => ({
        ...s,
        disabled: usedByOthers.includes(s.value)
      }))
    }
  },
  methods: {
    statusIcon(status) {
      return this.$storex.chats.statusIcon(status)
    },
    statusLabel(status) {
      return this.$storex.chats.statusLabel(status)
    },

    // ── New Task / Subtask ───────────────────────────────────────────────────
    openNewTask({ parentId, status } = {}) {
      this.newTask = {
        ...DEFAULT_NEW_TASK(),
        parentId: parentId || null,
        status: status || this.$storex.kanban.sprintColumns?.[0]?.value || 'todo'
      }
      this.showNewTask = true
      this.$nextTick(() => this.$refs.taskNameInput?.focus())
    },
    closeNewTask() {
      this.showNewTask = false
    },
    confirmNewTask() {
      if (!this.newTask.name?.trim()) return
      this.$emit('task-created', {
        name: this.newTask.name.trim(),
        mode: this.newTask.mode,
        status: this.newTask.status,
        parentId: this.newTask.parentId || null,
        profiles: this.newTask.selectedProfiles.map(p => p.name),
        llm_model: this.newTask.llm_model || null
      })
      this.closeNewTask()
    },
    onProfilesChanged(profiles) {
      this.newTask.selectedProfiles = profiles || []
    },
    onModelChanged(modelName) {
      this.newTask.llm_model = modelName || null
    },

    // ── Add existing ─────────────────────────────────────────────────────────
    openAddExisting() {
      this.selected = []
      this.candidateSearch = ''
      this.showAddExisting = true
    },
    closeAddExisting() {
      this.showAddExisting = false
    },
    confirmAddExisting() {
      if (!this.selected.length) return
      this.$emit('tasks-added', { taskIds: [...this.selected] })
      this.closeAddExisting()
    },

    // ── Column editor ────────────────────────────────────────────────────────
    openColumnEditor(column = null) {
      const used = this.$storex.kanban.sprintColumns.map(c => c.status)
      const firstFree = this.$storex.chats.statusList.find(s => !used.includes(s.value))
      this.columnEditor = {
        open: true,
        isNew: !column,
        id: column?.id || null,
        title: column?.title || '',
        status: column?.status || firstFree?.value || 'todo'
      }
    },
    closeColumnEditor() {
      this.columnEditor = DEFAULT_COLUMN_EDITOR()
    },
    confirmColumn() {
      if (!this.columnEditor.status) return
      this.$emit('save-column', {
        id: this.columnEditor.id,
        isNew: this.columnEditor.isNew,
        title: this.columnEditor.title.trim(),
        status: this.columnEditor.status
      })
      this.closeColumnEditor()
    },
    removeColumnFromEditor() {
      const id = this.columnEditor.id
      this.closeColumnEditor()
      if (id) this.$emit('delete-column', { id })
    },
    openRemoveColumn(column) {
      this.columnToRemove = column
    },
    confirmRemoveColumn() {
      if (!this.columnToRemove) return
      this.$emit('delete-column', { id: this.columnToRemove.id })
      this.columnToRemove = null
    }
  }
}
</script>
